const std::vector<Item>& items() { return kItems; }
int count() { return (int)kItems.size(); }

juce::String nameOf(int index)
{
    return (index >= 0 && index < count()) ? juce::String(kItems[(size_t)index].name)
                                           : juce::String();
}

juce::String categoryOf(int index)
{
    return (index >= 0 && index < count()) ? juce::String(kItems[(size_t)index].category)
                                           : juce::String();
}

// ==========================================================================
// applyInit
// 全パラメータを既定値へ戻す。
// setValueNotifyingHost() を使うのでメッセージスレッドから呼ぶこと。
// ==========================================================================
void applyInit(QuadMorphFilterAudioProcessor& proc)
{
    for (auto* p : proc.getParameters())
        if (auto* rp = dynamic_cast<juce::RangedAudioParameter*>(p))
        {
            // colorTheme は「見た目の好み」なので Init では変えない。
            // 音に関係しないうえ、初期化のたびに配色が戻ると煩わしいため。
            if (rp->paramID == "colorTheme")
                continue;

            rp->setValueNotifyingHost(rp->getDefaultValue());
        }
}

// ==========================================================================
// apply
// 既定値へ戻してから "id=value;..." を順に適用する。
// 前のプリセットの設定が residual として残らないことを保証する。
// ==========================================================================
void apply(QuadMorphFilterAudioProcessor& proc, int index)
{
    if (index < 0 || index >= count()) return;

    applyInit(proc);

    const juce::String data(kItems[(size_t)index].params);

    for (const auto& pairText : juce::StringArray::fromTokens(data, ";", ""))
    {
        const auto trimmed = pairText.trim();
        if (trimmed.isEmpty()) continue;

        const auto id = trimmed.upToFirstOccurrenceOf("=", false, false).trim();
        const auto valueText = trimmed.fromFirstOccurrenceOf("=", false, false).trim();
        if (id.isEmpty() || valueText.isEmpty()) continue;

        auto* prm = proc.apvts.getParameter(id);
        if (prm == nullptr)
        {
            // ID の書き間違いを開発中に気付けるようにする
            jassertfalse;
            continue;
        }

        // 実値 → 0-1 正規化。Choice / Bool もインデックス値がそのまま通る。
        prm->setValueNotifyingHost(prm->convertTo0to1(valueText.getFloatValue()));
    }
}

